const guideSlugs:Record<string,string>={date:'date-difference',business:'business-days',unit:'unit-conversion',travel:'travel-expense',interest:'savings-interest',parttime:'part-time-insurance',wage:'wage-conversion',insurance:'part-time-insurance',housingPlan:'housing-subscription-plan',capacity:'housing-loan-capacity',budget:'monthly-budget-plan',rentCompare:'jeonse-monthly-rent',prepayment:'early-loan-repayment',retirement:'retirement-leave-pay',parentalLeave:'parental-leave-income',carCost:'car-ownership-cost',moving:'moving-budget'}
