function CalculatorEditorial({id}:{id:string}){const note=contentNotes[id],tool=tools.find(item=>item.id===id),example=calculatorExamples[id];if(!note||!tool)return null;const guide=guideSlugs[id],sources=officialSources[id]||[];return <section className="calculator-editorial" aria-labelledby="calculator-method-title"><small>HOW IT WORKS</small><h3 id="calculator-method-title">{tool.title} 계산 방법과 주의사항</h3><p>{note[0]}</p><p>{note[1]}</p>{example&&<div className="calculation-example"><small>EXAMPLE</small><h4>계산 예제</h4><dl><div><dt>입력</dt><dd>{example[0]}</dd></div><div><dt>계산</dt><dd>{example[1]}</dd></div><div><dt>해석</dt><dd>{example[2]}</dd></div></dl></div>}{sources.length>0&&<p className="official-sources"><b>공식 확인:</b> {sources.map(([label,url],index)=><span key={url}>{index>0?' · ':''}<a href={url} target="_blank" rel="noopener noreferrer">{label}</a></span>)}</p>}<div><b>최종 검토</b><span>2026년 8월 · 결과는 입력 조건에 따른 참고값입니다.</span>{guide&&<a href={`/guides/${guide}`}>상세 계산 가이드 읽기 →</a>}</div></section>}
function MainApp(){
 const [initialAuth]=useState<CachedAuth>(cachedAuth)
 const [shared]=useState(()=>{const value=sharedFromLocation();return value&&tools.some(tool=>tool.id===value.calculatorType)?value:null});const [shortShareToken]=useState(shortShareTokenFromLocation);const [active,setActive]=useState(shared?.calculatorType||'');const [query,setQuery]=useState('');const [category,setCategory]=useState('전체');const [restoreInput,setRestoreInput]=useState<Record<string,unknown>|null>(()=>shared?{...(shared.input as Record<string,unknown>),_calculatorType:shared.calculatorType,_restoreAt:Date.now()}:null);const [shareData,setShareData]=useState<SharedCalculation|null>(shared);const [shareLink,setShareLink]=useState('');const [member,setMember]=useState<Member|null>(()=>initialAuth==='member'?{id:0,email:''}:null);const [authReady,setAuthReady]=useState(initialAuth!=='checking');const [historyLoading,setHistoryLoading]=useState(initialAuth!=='guest');const [history,setHistory]=useState<DisplayHistory[]>([]);const [saved,setSaved]=useState(shared?'공유받은 계산 내용을 불러왔습니다.':shortShareToken?'공유 계산을 불러오는 중…':'')
 const [featured]=useState(()=>calculatorTools[Math.floor(Math.random()*calculatorTools.length)])
 useEffect(()=>{if(window.location.pathname==='/')setDocumentMeta('WonderLife 생활 도구','날짜·금융 계산부터 생활 자료와 유용한 사이트까지, 일상에 필요한 답을 한곳에서 확인하세요.','/')},[])
 useEffect(()=>{const syncPath=()=>{const calculatorMatch=window.location.pathname.match(/^\/calculators\/([^/]+)\/?$/),dataMatch=window.location.pathname.match(/^\/data\/([^/]+)\/?$/),id=calculatorMatch?calculatorIdBySlug[calculatorMatch[1]]:dataMatch?dataIdBySlug[dataMatch[1]]:'';if(id&&tools.some(tool=>tool.id===id)){setActive(id);setRestoreInput(null);requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById('workspace')?.scrollIntoView({block:'start'})))}};syncPath();window.addEventListener('popstate',syncPath);return()=>window.removeEventListener('popstate',syncPath)},[])
 useEffect(()=>{if(!active||!calculatorSlugs[active])return;const selected=tools.find(item=>item.id===active);if(!selected)return;const title=`${selected.title} | WonderLife`;const description=`${selected.desc}. 계산 기준과 가정을 확인하고 로그인 없이 바로 계산하세요.`;document.title=title;document.querySelector('meta[name="description"]')?.setAttribute('content',description);document.querySelector('meta[property="og:title"]')?.setAttribute('content',title);document.querySelector('meta[property="og:description"]')?.setAttribute('content',description);let canonical=document.querySelector<HTMLLinkElement>('link[rel="canonical"]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.appendChild(canonical)}canonical.href=window.location.origin+calculatorPath(active)},[active])
 useEffect(()=>{const meta=dataMeta[active];if(meta)setDocumentMeta(`${meta[0]} | WonderLife`,meta[1],dataPath(active))},[active])
 useEffect(()=>{const scrollToHash=()=>{const hash=window.location.hash.slice(1),id=hash.startsWith('share=')||hash.startsWith('s=')?'workspace':decodeURIComponent(hash);if(!id)return;requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})))};scrollToHash();window.addEventListener('hashchange',scrollToHash);return()=>window.removeEventListener('hashchange',scrollToHash)},[])
 useEffect(()=>{const navigate=(event:Event)=>{const detail=(event as CustomEvent<{id:string;input?:Record<string,unknown>}>).detail;setActive(detail.id);setRestoreInput(detail.input?{...detail.input,_calculatorType:detail.id,_restoreAt:Date.now()}:null);setShareData(null);requestAnimationFrame(()=>document.getElementById('workspace')?.scrollIntoView({behavior:'smooth'}))};window.addEventListener('wonderlife:navigate',navigate);return()=>window.removeEventListener('wonderlife:navigate',navigate)},[])
 useEffect(()=>{if(!shortShareToken)return;let alive=true;api.publicShare(shortShareToken).then(item=>{if(!alive||!tools.some(tool=>tool.id===item.calculatorType))throw new Error('invalid share');const input=JSON.parse(item.inputJson),result=JSON.parse(item.resultJson),payload:SharedCalculation={calculatorType:item.calculatorType,title:item.title,input,result,version:1};setActive(item.calculatorType);setRestoreInput({...input,_calculatorType:item.calculatorType,_restoreAt:Date.now()});setShareData(payload);setSaved('공유받은 계산 내용을 불러왔습니다.');requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById('workspace')?.scrollIntoView({behavior:'smooth'})))}).catch(()=>{if(alive)setSaved('공유 링크가 만료되었거나 존재하지 않습니다.')});return()=>{alive=false}},[shortShareToken])
 useEffect(()=>{let alive=true;(async()=>{try{const m=await api.me();if(!alive)return;sessionStorage.removeItem('wonderlife:member');sessionStorage.setItem('wonderlife:auth','member');setMember(m);setAuthReady(true);setHistoryLoading(true);try{setHistory(await api.histories())}catch{setHistory([])}finally{if(alive)setHistoryLoading(false)}}catch{if(alive){sessionStorage.removeItem('wonderlife:member');sessionStorage.setItem('wonderlife:auth','guest');setMember(null);setAuthReady(true);setHistory([]);setHistoryLoading(false)}}})();return()=>{alive=false}},[])
 const categories=['전체',...Array.from(new Set(calculatorTools.map(x=>x.group)))];const visible=calculatorTools.filter(x=>(category==='전체'||x.group===category)&&(x.title+x.desc+x.group).includes(query));const tool=tools.find(x=>x.id===active);const displayHistory=history.filter(validHistory)
 const activeHistory=displayHistory.filter(x=>x.calculatorType===active).slice(0,5)
 const record=async(title:string,input:unknown,result:unknown)=>{setShareData({calculatorType:active,title,input,result,version:1});setShareLink('');const body:SaveHistory={calculatorType:active,title,inputJson:JSON.stringify(input),resultJson:JSON.stringify(result)};if(member){try{const item=await api.save(body);setHistory(v=>[item,...v.filter(x=>x.calculatorType!==active||x.id!==item.id)].filter((item,index,all)=>all.slice(0,index+1).filter(x=>x.calculatorType===item.calculatorType).length<=5));setSaved('계정에 자동 저장했습니다.')}catch{setSaved('저장하지 못했습니다. 다시 계산해 주세요.')}}else setSaved('비회원 계산은 저장하지 않습니다.');setTimeout(()=>setSaved(''),2200)}
 const remove=async(item:DisplayHistory)=>{await api.remove(item.id);setHistory(v=>v.filter(x=>x.id!==item.id))}
 const restore=(item:DisplayHistory)=>{try{const input=JSON.parse(item.inputJson),result=JSON.parse(item.resultJson);setActive(item.calculatorType);setRestoreInput({...input,_calculatorType:item.calculatorType,_restoreAt:Date.now()});setShareData({calculatorType:item.calculatorType,title:item.title,input,result,version:1});setShareLink('');requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById('workspace')?.scrollIntoView({behavior:'smooth'})))}catch{setSaved('저장된 입력값을 불러오지 못했습니다.')}}
 const shareCalculation=async()=>{if(!shareData||!member){setSaved('공유 링크를 만들려면 Google 로그인이 필요합니다.');return}try{const body:SaveHistory={calculatorType:shareData.calculatorType,title:shareData.title,inputJson:JSON.stringify(shareData.input),resultJson:JSON.stringify(shareData.result)},created=await api.createShare(body),url=shortShareUrl(created.token);setShareLink(url);if(navigator.share){await navigator.share({title:`WonderLife · ${shareData.title}`,text:'WonderLife 계산 입력과 결과를 공유합니다.',url});setSaved('짧은 공유 링크를 만들었습니다.')}else{await navigator.clipboard.writeText(url);setSaved('짧은 공유 링크를 복사했습니다.')}}catch(error){if(error instanceof DOMException&&error.name==='AbortError')return;setSaved(error instanceof Error?error.message:'공유 링크를 만들지 못했습니다.')}}
 const HistoryRows=({items}:{items:DisplayHistory[]})=><div className="history-list">{items.map(item=><article key={item.id}><div className="history-leading"><b title={item.title}>{item.title}</b><span className="history-input" title={historyInput(item)}>{historyInput(item)}</span></div><strong title={historyMain(item)}>{historyMain(item)}</strong><div className="history-actions"><small>{historyTime(item.createdAt)}</small><button aria-label={`${item.title} 입력값 불러오기`} onClick={()=>restore(item)}>불러오기</button><button aria-label={`${item.title} 이력 삭제`} onClick={()=>void remove(item)}>삭제</button></div></article>)}</div>
 const login=()=>{sessionStorage.setItem('wonderlife:auth','checking');setHistory([]);setHistoryLoading(true)}
 const logout=(event:MouseEvent<HTMLAnchorElement>)=>{event.preventDefault();sessionStorage.removeItem('wonderlife:member');sessionStorage.setItem('wonderlife:auth','guest');setMember(null);setAuthReady(true);setHistory([]);setHistoryLoading(false);requestAnimationFrame(()=>window.location.assign('/logout'))}
 const selectTool=(id:string)=>{setActive(id);setRestoreInput(null);setShareData(null);setShareLink('');if(calculatorSlugs[id]){window.history.pushState({},'',calculatorPath(id));window.dispatchEvent(new Event('wonderlife:location'))}requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById('workspace')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})))}
 const selectData=(id:string)=>{setActive(id);setRestoreInput(null);setShareData(null);setShareLink('');window.history.pushState({},'',dataPath(id));window.dispatchEvent(new Event('wonderlife:location'));requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById('workspace')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})))}
 const goTop=()=>window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})
 return <div className="app"><SiteHeader account={<div className="account">{!authReady?<span className="account-loading">로그인 확인 중…</span>:member?<><span>{member.email}</span><a href="/logout" onClick={logout}>로그아웃</a></>:<a className="login" href="/oauth2/authorization/google" onClick={login}>Google로 로그인</a>}</div>}/>
 <main><section className="hero"><div><p className="eyebrow">DAILY TOOLKIT</p><h1>복잡한 일상을<br/><em>가볍고 정확하게.</em></h1><p>날짜·금융 계산부터 생활 자료와 유용한 사이트까지, 필요한 답을 한곳에서 확인하세요.</p></div><div className="hero-card"><span>오늘 가장 많이 찾는 계산</span><b>{featured.title}</b><button onClick={()=>selectTool(featured.id)}>바로 계산하기 →</button></div></section>
 <section id="tools" className="catalog"><div className="section-title"><div><small>ALL CALCULATORS</small><h2>무엇을 계산할까요?</h2></div><input aria-label="계산기 검색" placeholder="이름·설명·분야 검색" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="category-chips" aria-label="계산기 카테고리">{categories.map(item=><button className={category===item?'selected':''} onClick={()=>setCategory(item)} key={item}>{item}</button>)}</div><div className="cards">{visible.map(x=><a className={'tool-card '+(active===x.id?'active':'')} href={calculatorPath(x.id)} key={x.id} onClick={event=>{event.preventDefault();selectTool(x.id)}}><i>{x.icon}</i><span><b>{x.title}</b><small>{x.desc}</small></span><em>→</em></a>)}</div>{!visible.length&&<div className="empty-history">검색 조건에 맞는 계산기가 없습니다.</div>}</section>
 <section id="data" className="life-data"><div className="section-title"><div><small>LIFE DATA</small><h2>생활 자료</h2><p>공식 기준 이력과 계산 원리를 한곳에서 확인하세요.</p></div></div><div className="data-cards"><a href={dataPath('minimum')} onClick={event=>{event.preventDefault();selectData('minimum')}}><i>₩</i><span><b>연도별 최저시급</b><small>2011년부터 공식 시급·일급·월 환산액</small></span><em>표 보기 →</em></a><a href={dataPath('salaryTable')} onClick={event=>{event.preventDefault();selectData('salaryTable')}}><i>급</i><span><b>연도별 연봉 실수령액</b><small>2020~2026년 보험료·세금 상세 비교</small></span><em>표 보기 →</em></a><a href={dataPath('holidays')} onClick={event=>{event.preventDefault();selectData('holidays')}}><i>휴</i><span><b>연도별 공휴일</b><small>2020~2026년 법정·대체공휴일과 선거일</small></span><em>표 보기 →</em></a><a href="/guides"><i>?</i><span><b>계산 가이드</b><small>계산식, 차이가 나는 이유와 자주 묻는 질문</small></span><em>읽기 →</em></a></div></section>
 {tool&&<section id="workspace" className="workspace"><div className="calc-head"><i>{tool.icon}</i><div><small>{tool.group}</small><h2>{tool.title}</h2><p>{tool.desc}</p></div></div><Calculator id={active} restoreInput={restoreInput} onCalculated={(title,input,result)=>void record(title,input,result)}/>{shareData&&<div className="share-panel"><div><small>{shared||shortShareToken?'SHARED CALCULATION':'SHARE RESULT'}</small><b>{String((shareData.result as {main?:unknown})?.main||shareData.title)}</b><span>로그인 회원은 짧은 링크를 만들 수 있고, 링크를 받은 사람은 로그인 없이 볼 수 있습니다. 개인정보는 포함하지 마세요.</span></div>{member?<button type="button" onClick={()=>void shareCalculation()}>공유하기</button>:<a className="share-login" href="/oauth2/authorization/google" onClick={login}>공유하려면 Google 로그인이 필요합니다</a>}{shareLink&&<input aria-label="계산 공유 링크" value={shareLink} readOnly onFocus={event=>event.currentTarget.select()}/>}</div>}{saved&&<div className="save-row"><b>{saved}</b></div>}{activeHistory.length>0&&<div className="calculator-history"><div className="history-heading"><div><small>RECENT 5</small><h3>{tool.title} 최근 이력</h3></div><span>{member?'계산기별 최근 5개가 계정에 저장됩니다.':'로그인 회원만 이력이 저장됩니다.'}</span></div><HistoryRows items={activeHistory}/></div>}<div className="related-tools"><small>RELATED TOOLS</small><h3>함께 쓰면 좋은 계산기</h3><div>{calculatorTools.filter(x=>x.id!==active&&x.group===tool.group).slice(0,3).map(x=><button key={x.id} onClick={()=>selectTool(x.id)}><b>{x.title}</b><span>{x.desc}</span></button>)}</div></div></section>}
 <section id="history" className="history"><div className="section-title"><div><small>ALL HISTORY</small><h2>전체 계산 이력</h2><p>{member?'계산기별 최근 5개가 로그인 계정에 자동 저장됩니다.':'비회원 계산은 브라우저나 서버에 저장하지 않습니다.'}</p></div></div>{historyLoading?<div className="empty-history history-loading">계산 이력을 불러오는 중…</div>:displayHistory.length?<HistoryRows items={displayHistory}/>:<div className="empty-history">{member?'아직 계산 이력이 없습니다. 계산기를 실행하면 계산기별 최근 5개까지 기록됩니다.':'계산 이력을 사용하려면 Google로 로그인해 주세요.'}</div>}</section>
 </main><button className="top-button" onClick={goTop} aria-label="페이지 맨 위로 이동"><span>↑</span> 맨 위</button><nav className="mobile-bottom-nav" aria-label="모바일 빠른 메뉴"><a href="/">홈</a><a href="#tools">계산기</a><a href="/links">사이트</a><a href="#history">이력</a><a href="/guides">가이드</a></nav><footer><b>WonderLife</b><span>계산 결과는 참고용이며 중요한 금융·세무 결정 전 공식 기관 또는 전문가와 확인하세요.</span><nav className="footer-links"><a href="/guides">계산 가이드</a><a href="/links">생활 사이트</a><a href="/about">서비스 소개</a><a href="/privacy">개인정보처리방침</a><a href="/terms">이용약관</a><a href="/contact">문의</a></nav></footer></div>}

const trustPages:Record<string,{title:string;body:string[]}>= {
 '/about':{title:'WonderLife 소개',body:['WonderLife는 날짜, 단위, 비용과 대출처럼 일상에서 자주 만나는 계산을 쉽고 투명하게 제공하는 생활 도구 모음입니다.','계산 결과와 함께 적용한 조건과 공식 자료의 기준 연도를 표시하며, 사용자가 결과의 의미와 한계를 이해할 수 있도록 설명합니다. 비회원 계산은 저장하지 않으며 Google 로그인 회원만 본인의 계산 이력을 저장·조회·삭제할 수 있습니다.']},
 '/privacy':{title:'개인정보처리방침',body:['비회원이 실행한 계산의 입력값과 결과는 브라우저 또는 서버에 저장하지 않습니다. Google 로그인 회원이 실행한 계산만 계정 이력으로 서버에 저장합니다.','로그인 회원이 공유 기능을 선택하면 계산 입력값과 결과를 난수 링크와 함께 서버에 보관합니다. 링크를 아는 사람은 로그인 없이 내용을 볼 수 있으므로 공유 내용에는 개인정보를 입력하지 마세요. 회원별 공유 자료는 최근 50개로 제한됩니다.','Google 로그인 회원은 계정 식별에 필요한 Google 계정 식별자와 이메일 및 계산 이력을 서버에 보관합니다. 저장된 계산 이력은 로그인한 본인만 조회하고 삭제할 수 있습니다. 광고가 활성화된 경우 Google AdSense가 쿠키 또는 유사 기술을 사용할 수 있으며, 자세한 내용은 Google의 광고 개인정보 안내를 따릅니다. 계정 및 데이터 삭제 문의는 meet.wonderlife@gmail.com으로 접수할 수 있습니다.']},
 '/terms':{title:'이용약관 및 계산 안내',body:['WonderLife의 계산 결과는 일반적인 정보 제공을 위한 참고값입니다. 대출 실제 납입액은 금융기관의 일수 계산, 중도상환, 수수료와 계약 조건에 따라 달라질 수 있습니다. 급여 실수령액은 회사 처리, 개인 공제, 보험 기준소득 결정과 연말정산에 따라 달라질 수 있습니다.','중요한 금융·세무·법률 결정을 내리기 전에는 해당 기관의 공식 안내 또는 전문가의 확인을 권합니다. 서비스의 계산 오류를 발견하면 입력 조건과 함께 문의해 주세요.']},
 '/contact':{title:'문의',body:['계산 기준, 오류 제보, 개인정보 또는 서비스 관련 문의는 meet.wonderlife@gmail.com으로 보내주세요. 계산 오류 제보 시 계산기 이름, 입력 조건, 기대한 결과와 참고한 공식 자료를 알려주시면 확인에 도움이 됩니다.']}
}
function TrustPage({page}:{page:{title:string;body:string[]}}){useEffect(()=>setDocumentMeta(`${page.title} | WonderLife`,page.body[0]),[page]);return <div className="app"><SiteHeader/><main className="trust-page"><a href="/">← 계산기로 돌아가기</a><h1>{page.title}</h1>{page.body.map((p,i)=><p key={i}>{p}</p>)}</main></div>}
function MethodologyPage(){useEffect(()=>setDocumentMeta('계산 기준과 변경 이력 | WonderLife','WonderLife가 금액, 날짜, 세율과 공식 자료를 계산하고 검토하는 원칙을 공개합니다.','/methodology'),[]);return <div className="app"><SiteHeader/><main className="methodology-page"><a href="/">← WonderLife 홈</a><p className="eyebrow">CALCULATION METHODOLOGY</p><h1>계산 기준과 변경 이력</h1><p className="methodology-lead">결과를 어떻게 계산하고 어떤 자료를 기준으로 검토하는지 공개합니다. 계산기는 일반적인 계획을 돕는 참고 도구이며 개인의 계약·신고·급여명세를 대신하지 않습니다.</p><section><h2>금액과 반올림</h2><p>금액은 내부 계산에서 소수 정밀도를 유지하고 결과를 표시할 때만 원 단위로 반올림합니다. 세금이나 금융기관이 원 단위 절사·일할 계산을 적용하는 경우 실제 값과 차이가 날 수 있습니다.</p></section><section><h2>날짜와 시간대</h2><p>날짜는 <code>YYYY-MM-DD</code> 달력 날짜로 처리하며 일수 차이는 일광절약시간의 영향을 피하도록 지역 정오를 기준으로 계산합니다. 도시 시각 변환에는 IANA 시간대 식별자를 사용합니다.</p></section><section><h2>금융·근로 기준</h2><p>요율과 상·하한이 있는 계산은 화면에 적용 연도와 가정을 표시합니다. 공식 기관 자료를 우선하고, 확정되지 않은 대출 승인액이나 법적 수급액으로 표현하지 않습니다.</p></section><section><h2>자료 검토와 수정</h2><p>새 연도 자료가 발표되면 기존 적용 연도의 계산을 보존하면서 새 기준을 추가합니다. 오류 제보는 계산기명, 입력 조건, 예상 결과와 확인한 공식 자료를 포함해 문의 페이지로 접수할 수 있습니다.</p></section><section className="methodology-log"><h2>주요 변경 이력</h2><ul><li><b>2026-08-31</b> 시급·월급·연봉 변환기와 계산기별 실제 예제를 추가했습니다.</li><li><b>2026-08-30</b> 계산기·생활 자료 독립 URL, canonical, sitemap과 공식 출처 표시를 적용했습니다.</li><li><b>2026-08-30</b> 2020~2026년 공휴일과 연도별 급여·사회보험 기준을 정리했습니다.</li></ul></section><p className="methodology-contact"><a href="/contact">계산 오류 또는 기준 자료 제보하기 →</a></p></main></div>}
function GuidePage(){const path=window.location.pathname;const slug=path.split('/')[2];const guide=guides.find(x=>x.slug===slug);useEffect(()=>{if(guide)setDocumentMeta(`${guide.title} | WonderLife`,guide.summary,path)},[guide,path]);if(!guide)return <GuideIndex/>;return <div className="app"><SiteHeader/><article className="guide-page"><a href="/guides">← 계산 가이드</a><p className="eyebrow">CALCULATION GUIDE</p><h1>{guide.title}</h1><p className="guide-lead">{guide.summary}</p>{guide.sections.map(section=><section key={section.title}><h2>{section.title}</h2>{section.paragraphs.map((p,i)=><p key={i}>{p}</p>)}</section>)}<section><h2>자주 묻는 질문</h2>{guide.faq.map(item=><details key={item.q}><summary>{item.q}</summary><p>{item.a}</p></details>)}</section><p className="guide-updated">마지막 검토: 2026년 8월 · 계산 결과는 참고용입니다.</p></article><TopButton/></div>}
function GuideIndex(){useEffect(()=>setDocumentMeta('계산 가이드 | WonderLife','계산식, 적용 기준, 결과가 달라지는 이유와 자주 묻는 질문을 도구별로 확인하세요.','/guides'),[]);return <div className="app"><SiteHeader/><main className="guide-index"><a href="/">← 계산기로 돌아가기</a><p className="eyebrow">WONDERLIFE GUIDES</p><h1>계산을 이해하는 생활 가이드</h1><p>공식 기준, 계산식, 결과가 달라지는 이유를 도구별로 정리했습니다.</p><a className="methodology-link" href="/methodology"><b>계산 기준과 변경 이력</b><span>반올림, 날짜, 공식 자료 검토 원칙을 확인하세요.</span><em>기준 보기 →</em></a><div className="guide-grid">{guides.map(g=><a href={`/guides/${g.slug}`} key={g.slug}><small>{g.category}</small><h2>{g.title}</h2><p>{g.summary}</p><b>읽어보기 →</b></a>)}</div></main><TopButton/></div>}
export default function App(){const path=window.location.pathname;const page=trustPages[path];return path==='/links'?<LinksPage/>:path==='/methodology'?<MethodologyPage/>:path.startsWith('/guides')?<GuidePage/>:page?<TrustPage page={page}/>:<MainApp/>}
